gcDiagnosticReproduction.patch:
--- a/scripts/performance/benchmark-workbench.mjs
+++ b/scripts/performance/benchmark-workbench.mjs
@@ -1,5 +1,5 @@
 import assert from 'node:assert/strict';
-import { performance } from 'node:perf_hooks';
+import { performance, PerformanceObserver, constants } from 'node:perf_hooks';
 import { cpus, totalmem } from 'node:os';
 import process from 'node:process';
 import { writeFile } from 'node:fs/promises';
@@ -9,6 +9,33 @@
 import { keyInput } from '../../dist/testing/index.js';
 import { searchPickerEntryById } from '../../dist/behavior/index.js';
 import { renderFramePlain } from '../../dist/renderer/index.js';
+const gcEvents = [], inputWindows = [];
+let activeInput;
+function collectGc(list) {
+  for (const entry of list) gcEvents.push({ startMs: entry.startTime,
+    endMs: entry.startTime + entry.duration, durationMs: entry.duration,
+    kind: entry.detail.kind === constants.NODE_PERFORMANCE_GC_MAJOR ? 'major'
+      : entry.detail.kind === constants.NODE_PERFORMANCE_GC_MINOR ? 'minor'
+      : entry.detail.kind === constants.NODE_PERFORMANCE_GC_INCREMENTAL ? 'incremental'
+      : String(entry.detail.kind), flags: entry.detail.flags });
+}
+const gcObserver = new PerformanceObserver(list => collectGc(list.getEntries()));
+gcObserver.observe({ entryTypes: ['gc'] });
+const probeInstrumentation = { now: () => performance.now(), record(sample) {
+  if (activeInput === undefined) return;
+  const endMs = performance.now();
+  activeInput.renderStages.push({ ...sample, startMs: endMs - sample.durationMs, endMs });
+} };
+async function observeInput(kind, trial, input) {
+  const window = { kind, trial, input: input.kind === 'text' ? input.text : input.key,
+    startMs: performance.now(), renderStages: [], hostWrites: [] };
+  activeInput = window;
+  try { return await runtime.handleInput(input); }
+  finally {
+    window.endMs = performance.now(); window.durationMs = window.endMs - window.startMs;
+    activeInput = undefined; inputWindows.push(window);
+  }
+}
 // Allocation runs are separate from headline timing runs: inspector sampling changes cost.
 const allocationRun = process.env['WORKBENCH_ALLOCATIONS'] === '1';
 let allocationSession;
@@ -67,13 +94,16 @@
 // Do not retain every historical frame/output in the benchmark observer: a real
 // terminal consumes writes rather than keeping hundreds of complete frame graphs.
 const host = { ...memoryHost, observer: {}, clock: clockHost.clock, async write(chunk, context) {
+  const writeBegin = performance.now();
+  const window = activeInput;
   writes++;
   if (writeDelayMs > 0) await delay(writeDelayMs);
   const receipt = await memoryHost.write(chunk, context);
   memoryHost.stdout.clear();
+  if (window !== undefined) window.hostWrites.push({ startMs: writeBegin, endMs: performance.now(), durationMs: performance.now() - writeBegin });
   return receipt;
 } };
-const runtime = createTuiRuntime({ app: incidentWorkbenchApp, host });
+const runtime = createTuiRuntime({ app: incidentWorkbenchApp, host, instrumentation: probeInstrumentation });
 const feedback = [], final = [], superseding = [], timerLag = [];
 const textInput = text => ({ kind: 'text', text, paste: false });
 function summary(samples) {
@@ -165,7 +195,7 @@
     const due = performance.now();
     const timer = delay(0).then(() => { typingEventLoopDelay.push(Math.max(0, performance.now() - due)); });
     const characterBegin = performance.now();
-    await runtime.handleInput(textInput(character));
+    await observeInput('character', i, textInput(character));
     typingFeedback.push(performance.now() - characterBegin);
     prefix += character;
     assert.equal(runtime.state().searchPicker.state.control.editor.input.text, prefix, 'Reliable character events retain order');
@@ -177,7 +207,7 @@
   await selectAll();
   await runtime.handleInput(textInput('gateway'));
   const cancelBegin = performance.now();
-  await runtime.handleInput(keyInput('escape'));
+  await observeInput('escape', i, keyInput('escape'));
   cancellation.push(performance.now() - cancelBegin);
   assert.equal(runtime.state().searchPicker.state.open, false);
   await runtime.dispatch({ kind: 'openSearchPicker' });
@@ -254,7 +284,19 @@
   globalThis.gc();
   retainedHeap.activeAfterInteraction = process.memoryUsage();
 }
+await delay(0);
+collectGc(gcObserver.takeRecords());
+gcObserver.disconnect();
+for (const window of inputWindows) {
+  window.overlappingGc = gcEvents.filter(gc => gc.startMs < window.endMs && gc.endMs > window.startMs);
+  window.renderWallMs = window.renderStages.reduce((sum, stage) => sum + stage.durationMs, 0);
+  window.hostWriteWallMs = window.hostWrites.reduce((sum, write) => sum + write.durationMs, 0);
+  window.beforeFirstRenderMs = window.renderStages.length === 0 ? null : window.renderStages[0].startMs - window.startMs;
+}
 const report = {
+  diagnostic: { kind: 'Separate instrumented delayed-write typing/Escape GC/render/write correlation',
+    note: 'PerformanceObserver and retained per-input render/write records perturb allocation and timing. No forced GC or GC tuning flags. GC overlaps are wall-time correlations, not additive costs or proof of cause. Windows include runtime dispatch/queue waiting; time before first render is not isolated queue time. This run cannot retrospectively attribute a prior uninstrumented outlier.',
+    inputWindows, gcEvents },
   metadata: { allocationSampling: allocationRun, measuredAt: new Date().toISOString(), runtime: process.version, platform: process.platform, architecture: process.arch, cpu: cpus()[0]?.model, logicalCpus: cpus().length, totalMemoryBytes: totalmem(), dataset: { incidents: incidentCount, commands: 4, deterministic: true }, terminalSize: { columns: 120, rows: 40 }, writeDelayMs, observedHostWrites: writes, sampleCount, warmupCount: 2, host: 'memory terminal output with native Node clock; no PTY/terminal-emulator presentation latency', workload: 'full incident workbench, unique literal trace queries plus character-by-character input and Escape, input through handleInput and committed frame; setup/index construction measured separately', limitations: 'Shared cloud CPU; polling adds up to ~1ms plus scheduling to final results. Two warmups precede unique, uncached measured queries. Module setup and initial/palette frames are measured separately; process launch and terminal-emulator presentation are excluded.' },
   characterToCommittedFeedbackMs: summary(typingFeedback),
   characterStreamToFinalResultMs: summary(typingFinal),
